import csv
from pathlib import Path

def generate_master_timeline(output_dir: Path) -> Path | None:
    master_records = []

    # Find all history report CSVs generated by any browser
    for history_csv in output_dir.glob("*_history_report.csv"):
        with open(history_csv, mode="r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            for row in reader:
                if row.get("visit_time"):
                    master_records.append({
                        "timestamp": row["visit_time"],
                        "browser": row.get("browser", "Unknown"),
                        "artifact_type": "History Visit",
                        "source_detail": row.get("title", ""),
                        "target_info": row.get("url", "")
                    })

    master_records.sort(key=lambda x: x["timestamp"] if x["timestamp"] else "")

    output_csv = output_dir / "chrome_master_timeline.csv"
    with open(output_csv, mode="w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=["timestamp", "browser", "artifact_type", "source_detail", "target_info"])
        writer.writeheader()
        writer.writerows(master_records)

    print(f"[+] Generated universal master timeline with {len(master_records)} chronological events.")
    print(f"[+] Saved timeline to: {output_csv}")
    return output_csv